<!doctype html><html lang="vi"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Quản lý chủ trọ</title><link href="https://cdn.jsdelivr.net/npm/bootstrap@5.3.3/dist/css/bootstrap.min.css" rel="stylesheet"><link rel="stylesheet" href="https://cdn.jsdelivr.net/npm/bootstrap-icons@1.11.3/font/bootstrap-icons.min.css"><link rel="stylesheet" href="/assets/css/style.css"><link rel="icon" href="/assets/pics/logo.webp" type="image/webp"></head>
<body><div class="app-shell"><?php renderApplicationSidebar($user,'/views/chutro/index.php'); ?><main class="main-panel"><header class="topbar"><div><h2>Quản lý chủ trọ</h2><p>Quản lý danh sách, tài khoản đăng nhập và trạng thái của các chủ trọ.</p></div><div class="top-actions"><button id="addOwner" class="btn btn-primary"><i class="bi bi-person-plus"></i> Thêm chủ trọ</button></div></header>
<section class="stats-grid"><div class="stat-card primary"><div class="icon"><i class="bi bi-people"></i></div><div><span>Tổng chủ trọ</span><strong id="ownerTotal">0</strong></div></div><div class="stat-card success"><div class="icon"><i class="bi bi-person-check"></i></div><div><span>Đang hoạt động</span><strong id="ownerActive">0</strong></div></div><div class="stat-card warning"><div class="icon"><i class="bi bi-person-lock"></i></div><div><span>Đã khóa</span><strong id="ownerLocked">0</strong></div></div></section>
<section class="card-panel mt-4"><div class="d-flex justify-content-between align-items-center gap-3 mb-3"><h5 class="mb-0">Danh sách chủ trọ</h5><div class="input-group" style="max-width:360px"><span class="input-group-text bg-white"><i class="bi bi-search"></i></span><input id="ownerSearch" class="form-control" placeholder="Tìm tên, tài khoản hoặc khu"></div></div><div id="ownerMessage" class="alert d-none"></div><div class="table-responsive"><table class="table table-modern align-middle"><thead><tr><th>Chủ trọ</th><th>Tên đăng nhập</th><th>Khu đang quản lý</th><th>Liên hệ</th><th>Trạng thái</th><th class="text-end">Thao tác</th></tr></thead><tbody id="ownerRows"><tr><td colspan="6" class="text-center text-muted py-4">Đang tải dữ liệu…</td></tr></tbody></table></div></section></main></div>

<div class="modal fade" id="ownerModal" tabindex="-1"><div class="modal-dialog modal-dialog-centered"><form id="ownerForm" class="modal-content"><div class="modal-header"><h5 id="ownerModalTitle" class="modal-title">Thêm chủ trọ</h5><button type="button" class="btn-close" data-bs-dismiss="modal"></button></div><div class="modal-body row g-3"><input type="hidden" id="ownerId"><div class="col-12"><label class="form-label">Họ tên</label><input id="ownerName" class="form-control" required></div><div class="col-md-6"><label class="form-label">Tên đăng nhập</label><input id="ownerUsername" class="form-control" required></div><div class="col-md-6" id="ownerPasswordWrap"><label class="form-label">Mật khẩu</label><input id="ownerPassword" type="password" minlength="6" class="form-control"></div><div class="col-md-6"><label class="form-label">Email</label><input id="ownerEmail" type="email" class="form-control"></div><div class="col-md-6"><label class="form-label">Số điện thoại</label><input id="ownerPhone" class="form-control"></div></div><div class="modal-footer"><button type="button" class="btn btn-light" data-bs-dismiss="modal">Hủy</button><button class="btn btn-primary">Lưu</button></div></form></div></div>
<div class="modal fade" id="ownerPasswordModal" tabindex="-1"><div class="modal-dialog modal-dialog-centered"><form id="ownerPasswordForm" class="modal-content"><div class="modal-header"><h5 class="modal-title">Cấp lại mật khẩu</h5><button type="button" class="btn-close" data-bs-dismiss="modal"></button></div><div class="modal-body"><input type="hidden" id="resetOwnerId"><p>Cấp mật khẩu mới cho <strong id="resetOwnerName"></strong>.</p><label class="form-label">Mật khẩu mới</label><input id="resetOwnerPassword" type="password" minlength="6" class="form-control" required><small class="text-muted">Tối thiểu 6 ký tự.</small></div><div class="modal-footer"><button type="button" class="btn btn-light" data-bs-dismiss="modal">Hủy</button><button class="btn btn-warning">Cấp lại mật khẩu</button></div></form></div></div>

<script src="https://cdn.jsdelivr.net/npm/bootstrap@5.3.3/dist/js/bootstrap.bundle.min.js"></script><script src="/assets/js/app.js"></script><script>(()=>{const host=document.getElementById('ownerRows'),search=document.getElementById('ownerSearch'),modal=bootstrap.Modal.getOrCreateInstance(document.getElementById('ownerModal')),passwordModal=bootstrap.Modal.getOrCreateInstance(document.getElementById('ownerPasswordModal'));let owners=[];const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c])),find=id=>owners.find(x=>Number(x.Id)===Number(id));function notify(text,type='success'){ownerMessage.className=`alert alert-${type}`;ownerMessage.textContent=text;setTimeout(()=>ownerMessage.classList.add('d-none'),3500)}
function render(){const q=search.value.trim().toLowerCase(),list=owners.filter(x=>[x.HoTen,x.TenDangNhap,x.Email,x.SoDienThoai,x.DanhSachKhu].join(' ').toLowerCase().includes(q));host.innerHTML=list.map(x=>{const active=Number(x.TrangThai)===1;return `<tr><td><strong>${esc(x.HoTen)}</strong><br><small class="text-muted">#${Number(x.Id)}</small></td><td><code>${esc(x.TenDangNhap)}</code></td><td><span class="badge bg-primary">${Number(x.SoKhu)} khu</span><br><small>${esc(x.DanhSachKhu||'Chưa quản lý khu nào')}</small></td><td>${esc(x.SoDienThoai||'—')}<br><small>${esc(x.Email||'—')}</small></td><td><span class="badge ${active?'bg-success':'bg-secondary'}">${active?'Hoạt động':'Đã khóa'}</span></td><td class="text-end text-nowrap"><button class="btn btn-sm btn-outline-primary edit-owner" data-id="${x.Id}" title="Sửa"><i class="bi bi-pencil-square"></i></button> <button class="btn btn-sm btn-outline-warning password-owner" data-id="${x.Id}" title="Cấp lại mật khẩu"><i class="bi bi-key"></i></button> <button class="btn btn-sm ${active?'btn-outline-secondary':'btn-outline-success'} lock-owner" data-id="${x.Id}" title="${active?'Khóa':'Mở khóa'}"><i class="bi ${active?'bi-lock':'bi-unlock'}"></i></button> <button class="btn btn-sm btn-outline-danger delete-owner" data-id="${x.Id}" title="Xóa"><i class="bi bi-trash"></i></button></td></tr>`}).join('')||'<tr><td colspan="6" class="text-center text-muted py-4">Không có chủ trọ phù hợp.</td></tr>';ownerTotal.textContent=owners.length;ownerActive.textContent=owners.filter(x=>Number(x.TrangThai)===1).length;ownerLocked.textContent=owners.filter(x=>Number(x.TrangThai)!==1).length}
async function load(){try{const r=await app.api('/api/chutro.php');owners=r.data||[];render()}catch(e){host.innerHTML=`<tr><td colspan="6" class="text-danger text-center py-4">${esc(e.message)}</td></tr>`}}search.oninput=render;addOwner.onclick=()=>{ownerForm.reset();ownerId.value='';ownerModalTitle.textContent='Thêm chủ trọ';ownerUsername.disabled=false;ownerPasswordWrap.hidden=false;ownerPassword.required=true;modal.show()};
document.addEventListener('click',async e=>{const edit=e.target.closest('.edit-owner'),pass=e.target.closest('.password-owner'),lock=e.target.closest('.lock-owner'),del=e.target.closest('.delete-owner');if(edit){const x=find(edit.dataset.id);ownerId.value=x.Id;ownerName.value=x.HoTen||'';ownerUsername.value=x.TenDangNhap||'';ownerUsername.disabled=true;ownerPasswordWrap.hidden=true;ownerPassword.required=false;ownerEmail.value=x.Email||'';ownerPhone.value=x.SoDienThoai||'';ownerModalTitle.textContent='Sửa chủ trọ';modal.show()}if(pass){const x=find(pass.dataset.id);ownerPasswordForm.reset();resetOwnerId.value=x.Id;resetOwnerName.textContent=x.HoTen;passwordModal.show()}if(lock){const x=find(lock.dataset.id),next=Number(x.TrangThai)===1?0:1;if(!confirm(`${next?'Mở khóa':'Khóa'} chủ trọ ${x.TenDangNhap}?`))return;await app.api(`/api/chutro.php?id=${x.Id}&action=trangThai`,{method:'PUT',body:JSON.stringify({TrangThai:next})});notify(next?'Đã mở khóa chủ trọ.':'Đã khóa chủ trọ.');load()}if(del){const x=find(del.dataset.id);if(!confirm(`Xóa chủ trọ ${x.TenDangNhap}? Các khu hiện có vẫn được giữ lại.`))return;await app.api('/api/chutro.php?id='+x.Id,{method:'DELETE'});notify('Đã xóa chủ trọ.');load()}});
ownerForm.onsubmit=async e=>{e.preventDefault();const id=ownerId.value,payload={HoTen:ownerName.value,TenDangNhap:ownerUsername.value,MatKhau:ownerPassword.value,Email:ownerEmail.value,SoDienThoai:ownerPhone.value};await app.api(id?`/api/chutro.php?id=${id}&action=sua`:'/api/chutro.php',{method:id?'PUT':'POST',body:JSON.stringify(payload)});modal.hide();notify(id?'Đã cập nhật chủ trọ.':'Đã thêm chủ trọ.');load()};ownerPasswordForm.onsubmit=async e=>{e.preventDefault();await app.api(`/api/chutro.php?id=${resetOwnerId.value}&action=capLaiMatKhau`,{method:'PUT',body:JSON.stringify({MatKhau:resetOwnerPassword.value})});passwordModal.hide();notify('Đã cấp lại mật khẩu.');};load()})();</script></body></html>
